/**
 * The app's own icons: single-colour line drawings on a 24-unit grid.
 *
 * They replace emoji (operator, 2026-09-24: アイコンをブラッシュアップして・単色がいい). An
 * emoji is drawn by the device's font in the device's colours, so the same button looked
 * different on the tablet and the Mac and never took the button's own colour when pressed.
 * These are drawn with `currentColor`, so a pressed button's icon turns with its text.
 *
 * All markup here is our own constant text, never anything from outside — which is the only
 * reason `innerHTML` is acceptable in `setIcon`.
 */

const PATHS = {
  play: '<path class="solid" d="M8 5.2v13.6a1 1 0 0 0 1.5.86l11-6.8a1 1 0 0 0 0-1.72l-11-6.8A1 1 0 0 0 8 5.2z"/>',
  pause:
    '<rect class="solid" x="6" y="4.5" width="4" height="15" rx="1.2"/><rect class="solid" x="14" y="4.5" width="4" height="15" rx="1.2"/>',
  volume:
    '<path d="M4 9.5h3.5L12 5.5v13l-4.5-4H4z"/><path d="M15.5 9a4.5 4.5 0 0 1 0 6"/><path d="M18.5 6.5a8 8 0 0 1 0 11"/>',
  muted:
    '<path d="M4 9.5h3.5L12 5.5v13l-4.5-4H4z"/><path d="M16 9.5l5 5"/><path d="M21 9.5l-5 5"/>',
  loop: '<path d="M17 3l3 3-3 3"/><path d="M4 11V9.5A3.5 3.5 0 0 1 7.5 6H20"/><path d="M7 21l-3-3 3-3"/><path d="M20 13v1.5a3.5 3.5 0 0 1-3.5 3.5H4"/>',
  expand:
    '<path d="M4 9V5.5A1.5 1.5 0 0 1 5.5 4H9"/><path d="M15 4h3.5A1.5 1.5 0 0 1 20 5.5V9"/><path d="M20 15v3.5a1.5 1.5 0 0 1-1.5 1.5H15"/><path d="M9 20H5.5A1.5 1.5 0 0 1 4 18.5V15"/>',
  link: '<path d="M10 14a4.5 4.5 0 0 0 6.4 0l3-3a4.5 4.5 0 0 0-6.4-6.4l-1.2 1.2"/><path d="M14 10a4.5 4.5 0 0 0-6.4 0l-3 3a4.5 4.5 0 0 0 6.4 6.4l1.2-1.2"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="M15.5 15.5L20.5 20.5"/>',
  captions:
    '<rect x="2.5" y="5" width="19" height="14" rx="3"/><path d="M10.5 10.2a2.2 2.2 0 1 0 0 3.6"/><path d="M17 10.2a2.2 2.2 0 1 0 0 3.6"/>',
  settings:
    '<path d="M4 7h9"/><path d="M17 7h3"/><circle cx="15" cy="7" r="2"/><path d="M4 17h3"/><path d="M11 17h9"/><circle cx="9" cy="17" r="2"/>',
  close: '<path d="M6 6l12 12"/><path d="M18 6L6 18"/>',
  trash:
    '<path d="M4 7h16"/><path d="M9.5 7V4.5h5V7"/><path d="M6.5 7l1 12.5h9l1-12.5"/><path d="M10.5 11v5"/><path d="M13.5 11v5"/>',
  refresh: '<path d="M20 12a8 8 0 1 1-2.3-5.6L20 8.5"/><path d="M20 4v4.5h-4.5"/>',
  grid: '<rect x="3.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.5"/>',
  minus: '<path d="M5 12h14"/>',
  plus: '<path d="M5 12h14"/><path d="M12 5v14"/>',
  enter: '<path d="M20 5v6a3 3 0 0 1-3 3H5"/><path d="M9 10l-4 4 4 4"/>',
} as const;

export type IconName = keyof typeof PATHS;

function isIconName(value: string | undefined): value is IconName {
  return value !== undefined && Object.hasOwn(PATHS, value);
}

/** The whole `<svg>` for one icon, sized by the stylesheet (`.ico`). */
export function iconMarkup(name: IconName): string {
  return `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${PATHS[name]}</svg>`;
}

/**
 * Puts an icon into an element, replacing only an earlier icon — any words beside it (the
 * 全部 on the play-all button) stay where they are.
 */
export function setIcon(element: Element, name: IconName): void {
  element.querySelector(':scope > svg.ico')?.remove();
  element.insertAdjacentHTML('afterbegin', iconMarkup(name));
}

/** Draws every `[data-icon]` under `root`. Run once over the page and once over each template. */
export function paintIcons(root: ParentNode): void {
  for (const element of root.querySelectorAll<HTMLElement>('[data-icon]')) {
    const name = element.dataset.icon;
    if (isIconName(name)) setIcon(element, name);
  }
}
